using namespace std;

struct Edge {
    int v, w;
};

const int INF = 10000000;
const int N = 210;
const int M = 21000;

vector<int> adj[M];
Edge edges[M];
int head[N], e;

void addEdge(int u, int v, int w) {
    edges[e] = {v, w};
    adj[u].push_back(e++);
    edges[e] = {u, 0};
    adj[v].push_back(e++);
}

int S, T;
int dist[N], q[N*2], arc[N], gap[N], inq[N], pre[N];

int maxFlow(int s, int t) {
    memset(arc, -1, sizeof(arc));
    memset(pre, -1, sizeof(pre));
    int qf=0, qr=0;
    q[qr++]=t; inq[t]=1; gap[0]++;
    dist[t]=0;
    while(qf<qr) {
        int u=q[qf++];
        for(auto i:adj[u]) {
            int v=edges[i].v;
            if(!inq[v]) {
                q[qr++]=v;
                inq[v]=1;
                dist[v]=dist[u]+1;
                gap[dist[v]]++;
                arc[v]=i;
            }
        }
    }
    int flow=0, low=INF, u=s;
    for(int i=0;i<N;++i) pre[i]=i;
    while(dist[s]<t) {
        bool pushed=false;
        for(int &i=arc[u];i!=-1;i=adj[u][i]) {
            if(edges[i].w && dist[edges[i].v]+1==dist[u]) {
                low=min(low,edges[i].w);
                pre[edges[i].v]=u;
                u=edges[i].v;
                if(u==t) {
                    for(int v=t;v!=s;v=pre[v]) {
                        int i=arc[pre[v]];
                        edges[i].w-=low;
                        edges[i^1].w+=low;
                    }
                    flow+=low;
                    low=INF;
                    u=s;
                }
                pushed=true;
                break;
            }
        }
        if(pushed) continue;
        int minDist=t+1;
        for(auto i:adj[u]) {
            if(edges[i].w && minDist>dist[edges[i].v]) {
                minDist=dist[edges[i].v];
                arc[u]=i;
            }
        }
        gap[dist[u]]--;
        if(gap[dist[u]]==0) break;
        dist[u]=minDist+1;
        gap[dist[u]]++;
        u=pre[u];
    }
    return flow;
}

